(x, y, t) => {
  const cx = 240, cy = 120;
  const g1x = 160+Math.sin(t*0.3)*80, g1y = 90+Math.cos(t*0.4)*60;
  const g2x = 340+Math.cos(t*0.25)*70, g2y = 160+Math.sin(t*0.35)*50;
  const g3x = 240+Math.sin(t*0.45+2)*100, g3y = 200+Math.cos(t*0.2+1)*70;
  const dx1 = x-g1x, dy1 = y-g1y, d1 = Math.sqrt(dx1*dx1+dy1*dy1)+1;
  const dx2 = x-g2x, dy2 = y-g2y, d2 = Math.sqrt(dx2*dx2+dy2*dy2)+1;
  const dx3 = x-g3x, dy3 = y-g3y, d3 = Math.sqrt(dx3*dx3+dy3*dy3)+1;
  const grav = (180/d1 + 150/d2 + 120/d3) * 0.08;
  const fx = -dx1/d1*grav - dx2/d1*grav*0.7 - dx3/d1*grav*0.5;
  const fy = -dy1/d1*grav - dy2/d1*grav*0.7 - dy3/d1*grav*0.5;
  const warp = Math.sin(x*0.015+t*0.4)*Math.cos(y*0.012-t*0.3)*12;
  const sx = x + fx + warp, sy = y + fy + Math.cos(x*0.012-t*0.35)*Math.sin(y*0.015+t*0.45)*12;
  const src = [
    [180+Math.sin(t*0.5)*90, 70+Math.cos(t*0.35)*50, 0.09, 2.2, 1.0],
    [320+Math.cos(t*0.4)*80, 150+Math.sin(t*0.6)*60, 0.11, 1.8, 0.85],
    [100+Math.sin(t*0.3+2)*110, 180+Math.cos(t*0.45+1)*70, 0.07, 2.5, 0.9],
    [380+Math.cos(t*0.55+3)*70, 50+Math.sin(t*0.5+2)*80, 0.13, 1.6, 0.75],
    [240+Math.sin(t*0.38+4)*130, 120+Math.cos(t*0.42)*90, 0.06, 2.8, 1.1],
    [60+Math.cos(t*0.6+5)*60, 220+Math.sin(t*0.48)*50, 0.1, 2.0, 0.8],
    [420+Math.sin(t*0.32)*50, 190+Math.cos(t*0.58+3)*60, 0.08, 2.4, 0.95]
  ];
  let aS = 0, iS = 0, kinetic = 0;
  for (const [sX, sY, f, sp, e] of src) {
    const d = Math.sqrt((sx-sX)**2 + (sy-sY)**2);
    const potential = Math.sin(d*f - t*sp) * e;
    const kFlow = Math.cos(d*f*0.6 + t*sp*0.8 + 2.0) * (1.0 - e*0.3);
    aS += potential;
    iS += Math.sin(d*f*0.8 + t*sp*0.5 + 1.2) * e;
    kinetic += kFlow;
  }
  kinetic /= 7;
  const act = aS/7, inh = iS/7;
  const energy = act*act + kinetic*kinetic;
  const potential = 1.0 - Math.min(energy * 0.5, 1.0);
  const flow = Math.atan2(kinetic, act) / Math.PI;
  const bg = (Math.sin(sx*0.035+sy*0.028+t*0.9) + Math.sin(sx*0.028-sy*0.035+t*1.3))/2;
  const dist = Math.sqrt((sx-cx)**2 + (sy-cy)**2), ang = Math.atan2(sy-cy, sx-cx);
  const spiral = (Math.sin(dist*0.06-ang*4-t*1.8) + Math.sin(dist*0.045+ang*5-t*1.4))*0.35;
  const vortex = Math.sin(ang*6 + dist*0.03 - t*2.5) * Math.exp(-dist*0.005) * 0.4;
  const rd = Math.tanh((act - inh*0.6 + bg*0.25 + spiral + vortex)*2.5);
  const cell = Math.tanh((Math.sin(sx*0.18)*Math.sin(sy*0.18) + Math.sin((sx+sy)*0.12+t*1.2)*0.6)*1.8)*0.25;
  const streams = Math.sin(sx*0.05+flow*6+t*1.5)*Math.cos(sy*0.04-flow*4-t*1.1)*0.2;
  const blend = rd*0.6 + cell*0.15 + streams*0.15 + kinetic*0.1;
  const v = blend*0.5+0.5;
  const pal = [
    [2,2,15],[5,10,50],[0,60,90],[0,180,160],[20,255,180],
    [180,255,50],[255,200,0],[255,100,20],[255,30,60],[200,0,120],[100,0,180],[2,2,15]
  ];
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
  const glow = Math.pow(Math.abs(rd), 0.6) * 1.4;
  const neon = Math.max(0, Math.abs(rd)-0.5)*3.0;
  const edge = (1.0 + neon*0.8) * glow;
  const deep = potential > 0.7 ? 0.6 : 1.0;
  return [
    Math.min(255, (pal[i][0]+(pal[i+1][0]-pal[i][0])*f + neon*40)*edge*deep)|0,
    Math.min(255, (pal[i][1]+(pal[i+1][1]-pal[i][1])*f + neon*30)*edge*deep)|0,
    Math.min(255, (pal[i][2]+(pal[i+1][2]-pal[i][2])*f + neon*50)*edge*deep)|0
  ];
}
